/* The laboratory order draws only what a contract holds — 30 September 2026 */
/* apps/web/src/features/OrderDetails.tsx carried a panel of four typed results, each with a unit, a
   reference range and, on two of them, a typed "High". A reference range is one of the numbers CLAUDE.md
   says lives in one place, and no contract holds a laboratory one: records.json#observations holds the
   ranges for the readings a nurse takes at the door, which are not a laboratory's tests. Nor does a value
   exist — medicines.json#labs has the synthetic laboratory answer with a reference, never a value. So the
   order names its tests from the laboratory's menu in vetting.json, says what comes back in the contract's
   words under the laboratory's own notice, and types no result, unit, range or flag. When a reviewed
   contract gives a laboratory test its range, the flag is derived from value and range there.

   Both phones typed the same four results, units, ranges and two "High"s under a count of the ones outside
   their range until 2 October 2026, two days after the web stopped, because this read the web alone. It reads
   the lab order on all three now: on a phone, the slices of OrdersView.swift and OrderScreens.kt that are the
   laboratory order's (the prescription beside it carries doses, which are not laboratory figures). */
{
  const slice = (f, code, from, to) => {
    const at = code.indexOf(from), end = to ? code.indexOf(to, at) : code.length;
    if (at < 0 || end < 0) throw new Error(`${f} no longer has ${at < 0 ? from : to}, which is where this check finds its laboratory order.`);
    return code.slice(at, end);
  };
  const strip = (text) => text.replace(/\{\/\*[\s\S]*?\*\/\}/g, " ").replace(/\/\*[\s\S]*?\*\//g, " ").replace(/(^|[^:"])\/\/[^\n]*/g, "$1 ");
  const menu = JSON.parse(read("packages/catalog/vetting.json")).roles.find((r) => r.id === "laboratory")?.scope?.options ?? [];
  const told = [];
  for (const [f, take, list, quote, reads] of [
    ["apps/web/src/features/OrderDetails.tsx", (code) => code, /const requested = \[([^\]]*)\];/, /'([^']+)'/g,
      [[/scopeFor\('laboratory'\)\?\.options/, "tests that are not read from the laboratory's menu"],
       ['<NotConnected of="laboratory-results"', "no laboratory notice over the order"],
       ["medicinesContract.screen.results.ordered", "no sentence from packages/catalog/medicines.json saying what the synthetic laboratory returns"]]],
    ["apps/ios/MyThuso/Features/OrdersView.swift", (code) => slice("apps/ios/MyThuso/Features/OrdersView.swift", code, "private struct LabFixture", "struct AnyButtonStyleBox"),
      /private let requested = \[([^\]]*)\]/, /"([^"]+)"/g,
      [[/Vetting\.scopeOptions\(for: "laboratory"\)/, "tests that are not read from the laboratory's menu (Vetting.scopeOptions)"],
       ['CapabilityNotice(of: "laboratory-results")', "no laboratory notice over the order"],
       ["Medicines.ResultsText.ordered", "no sentence from the generated MedicinesData saying what the synthetic laboratory returns"]]],
    ["apps/android/app/src/main/java/za/co/mythuso/ui/OrderScreens.kt",
      (code) => slice("apps/android/app/src/main/java/za/co/mythuso/ui/OrderScreens.kt", code, "private data class LabFixture", "private fun progressed")
        + slice("apps/android/app/src/main/java/za/co/mythuso/ui/OrderScreens.kt", code, "@Composable fun LabOrderScreen"),
      /private val requested = listOf\(([^)]*)\)/, /"([^"]+)"/g,
      [[/scopeFor\("laboratory"\)\?\.options/, "tests that are not read from the laboratory's menu (scopeFor)"],
       ['NotConnected("laboratory-results")', "no laboratory notice over the order"],
       ["MedicinesData.ResultsText.ordered", "no sentence from the generated MedicinesData saying what the synthetic laboratory returns"]]],
  ]) {
    const code = take(strip(read(f)));
    const found = [];
    const unit = code.match(/(?:m?mol|µmol|umol|µg|mg|g)\/(?:L|dL)\b|\b(?:U\/L|fL)\b/);
    if (unit) found.push(`a laboratory unit (${unit[0]})`);
    const keyed = code.match(/\b(result|value|range|unit|flag|low|high)\s*:\s*['"`\d<>]/);
    if (keyed) found.push(`a literal ${keyed[1]}`);
    const flag = code.match(/['"`](High|Low|Within range|Abnormal|All within range)['"`]/);
    if (flag) found.push(`the flag "${flag[1]}"`);
    const range = code.match(/['"`][^'"`\n]*(?:\d\s*[–—]\s*\d|[<>≤≥]\s*\d)[^'"`\n]*['"`]/);
    if (range) found.push(`a range (${range[0]})`);
    if (/reference range/i.test(code)) found.push("a reference range named on the screen");
    const requested = code.match(list);
    const tests = requested ? [...requested[1].matchAll(quote)].map((m) => m[1]) : [];
    if (!requested || !tests.length) found.push("no `requested` list of the tests the order asked for");
    for (const test of tests)
      if (!menu.includes(test)) found.push(`the test "${test}", which is not on the laboratory's menu in packages/catalog/vetting.json`);
    for (const [needle, missing] of reads)
      if (typeof needle === "string" ? !code.includes(needle) : !needle.test(code)) found.push(missing);
    if (found.length)
      throw new Error(`${f}'s laboratory order carries ${found.join("; ")}. No contract holds a laboratory reference range and the synthetic laboratory returns no value, so the order names its tests from the laboratory's menu and types no result, unit, range or flag.`);
    told.push(tests.length);
  }
  console.log(`The laboratory order · ${told.join(", ")} tests from the laboratory's menu on web, iOS and Android, no typed result, unit, range or flag, under the laboratory's own notice and in the medicines contract's words.`);
}

/* The step a laboratory order's custody ends on before release — 1 October 2026. All three platforms typed
   "Results verified · Checked by the laboratory's reviewing pathologist" above a notice saying no laboratory
   is connected, which claims a test was run and a pathologist read it when the synthetic laboratory runs
   nothing and hands back a reference. The step is medicines.json#screen.results.returned now, and both
   phones draw it from the generated MedicinesData. The web's OrderDetails.tsx reads the contract directly
   since 2 October 2026 and is held to the same.

   Also since 2 October: the partner's Results board (Fulfilment.tsx) said "Verified by the laboratory" and
   that an order still out waited on "the laboratory's own reviewing pathologist", and the web's badge said
   "Not yet verified". The board reads the step and the sentence release waits on (releaseWaits) from the
   contract, and the badge and both phones' standing say notReturned. The old words are refused in any quote
   — the board typed them in single ones, which the first version of this did not read. */
{
  const results = JSON.parse(read("packages/catalog/medicines.json")).screen.results;
  for (const [file, reads] of [
    ["apps/ios/MyThuso/Features/OrdersView.swift", ["Medicines.ResultsText.returned", "Medicines.ResultsText.notReturned"]],
    ["apps/android/app/src/main/java/za/co/mythuso/ui/OrderScreens.kt", ["MedicinesData.ResultsText.returned", "MedicinesData.ResultsText.notReturned"]],
    ["apps/web/src/features/OrderDetails.tsx", ["medicinesContract.screen.results.returned", "medicinesContract.screen.results.notReturned", "medicinesContract.screen.results.releaseWaits"]],
    ["apps/web/src/features/Fulfilment.tsx", ["const words = medicinesContract.screen.results;", "words.returned", "words.releaseWaits"]],
  ]) {
    const code = read(file);
    const old = code.match(/reviewing pathologist|own pathologist|pathologist has checked it|["'`‘]Results verified|Verified by the laboratory|Not yet verified/);
    if (old)
      throw new Error(`${file} says "${old[0]}". No laboratory is connected, no test is run and no pathologist checks anything; the step is "${results.returned}" and an order short of it is "${results.notReturned}", read from packages/catalog/medicines.json (MedicinesData on the phones).`);
    const typed = ["returned", "returnedDetail", "notReturned", "releaseWaits"].find((key) => code.includes(results[key]));
    const missing = reads.find((r) => !code.includes(r));
    if (missing || typed)
      throw new Error(`${file} ${typed ? `types medicines.json's screen.results.${typed}` : `does not read ${missing}`}. The laboratory order's custody words are packages/catalog/medicines.json's, generated for both phones, and a typed copy is the one that says "verified" again.`);
  }
}

/* The patient's home on three platforms — 1 October 2026 */
/* Four things a review found the three homes saying differently, each held here rather than trusted:

   1. The line under the home's figures — how many visits they come from, the last one's day, and that
      they are sample readings — is passport.json#onRecord's sentence on every platform. Android's metric
      cards carried a blood pressure with no date and no marker while iOS and the web said "Sample
      readings", because the sentence was typed twice and the third copy was simply dropped.
   2. "Next visit" is the visit at the door first. All three read the top of the visit list, and a
      booking is put at the top because it is the newest, so the home showed the visit booked last and
      Android's seeded visit already under way was never shown. Each home orders through its platform's
      nextFirst.
   3. Android's home names the nurse a visit names, from the vetting register, or nobody. It typed one
      nurse's name and photograph beside every visit, including a come-now request whose card said it
      was still looking for one.
   4. The CI document does not say the phones draw system-ui: what each phone bundles is read from the
      platform by emit-ci.mjs, and the sentence that said otherwise is not in the generator or the tokens.
   Each was proved to fire by breaking the source and restoring it. */
{
  const homeFail = (m) => { throw new Error(`The patient's home: ${m}`); };
  const strip = (code) => code.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/^\s*\/\/.*$/gm, " ");
  const androidCare = strip(read("apps/android/app/src/main/java/za/co/mythuso/ui/CareScreens.kt"));
  const iosHome = strip(read("apps/ios/MyThuso/Features/HomeView.swift"));
  const webHome = strip(read("apps/web/src/features/Dashboard.tsx"));
  const webApp = strip(read("apps/web/src/App.tsx"));
  const onRecord = JSON.parse(read("packages/catalog/passport.json")).onRecord?.sentence ?? "";

  /* 1. */
  if (!/\{count\}/.test(onRecord) || !/\{date\}/.test(onRecord) || !/Sample readings/.test(onRecord))
    homeFail("packages/catalog/passport.json#onRecord no longer carries {count}, {date} and the words \"Sample readings\".");
  for (const [file, code, reads] of [
    ["apps/web/src/features/Dashboard.tsx", webHome, /\{onRecord\}/],
    ["apps/ios/MyThuso/Features/HomeView.swift", iosHome, /PassportData\.onRecord\(/],
    ["apps/android/app/src/main/java/za/co/mythuso/ui/CareScreens.kt", androidCare, /PassportData\.onRecord\(/],
  ]) {
    if (/home visits on record|Sample readings/.test(code)) homeFail(`${file} types the on-record sentence. It is passport.json#onRecord's, read through the platform's passport module.`);
    if (!reads.test(code)) homeFail(`${file} no longer draws passport.json#onRecord under the home's readings, so a sample reading there carries no date and no marker.`);
  }

  /* 2. */
  if (!/const booked = nextFirst\(/.test(webApp)) homeFail("apps/web/src/App.tsx no longer orders the booked visits with nextFirst, so the home's next visit is the one booked last.");
  if (/store\.visits\.first\b/.test(iosHome) || !/Scheduling\.nextFirst\(store\.visits\)/.test(iosHome))
    homeFail("apps/ios/MyThuso/Features/HomeView.swift reads the top of store.visits as the next visit. Read Scheduling.nextFirst(store.visits).");
  const androidHome = androidCare.slice(androidCare.indexOf("fun HomeNextVisit"), androidCare.indexOf("fun RangeFoot"));
  if (/store\.visits\.(first|firstOrNull)\(\)|store\.visits\[0\]/.test(androidHome) || (androidHome.match(/Scheduling\.nextFirst\(store\.visits\)/g) ?? []).length < 2)
    homeFail("CareScreens.kt's HomeNextVisit or HomeMetrics reads the top of store.visits as the next visit. Read Scheduling.nextFirst(store.visits).");
  if (/\?\?\s*0\b/.test(iosHome.slice(iosHome.indexOf("private var metrics"), iosHome.indexOf("private var arranged"))))
    homeFail("HomeView.swift's figures default a missing reading to 0; a reading that is not on record is a dash, never 0/0 mmHg.");

  /* 3. */
  if (/Naledi|mythuso_nurse/.test(androidCare)) homeFail("CareScreens.kt types a nurse's name or portrait. The nurse is the one the visit names, read from the vetting register.");
  if (!/fun NurseRow\(nurse: VettingSubject/.test(androidCare)) homeFail("CareScreens.kt's NurseRow no longer takes the visit's nurse.");

  /* 4. */
  const ciDoc = read("docs/brand/CI.md");
  for (const [file, content] of [["scripts/emit-ci.mjs", read("scripts/emit-ci.mjs")], ["packages/design-tokens/tokens.json", read("packages/design-tokens/tokens.json")], ["docs/brand/CI.md", ciDoc]])
    if (/system-ui on iOS|On iOS and Android this wave|The Lovable identity is on the web only/.test(content))
      homeFail(`${file} says the phones draw system-ui or are not on the identity. Both bundle Outfit and Figtree since 29 September 2026; emit-ci.mjs reads that from the platforms.`);
  if (!/The phones bundle the same two faces: Outfit on iOS at \d{3}–\d{3}.*Android at \d{3}–\d{3}/.test(ciDoc))
    homeFail("docs/brand/CI.md no longer says, from the platforms, which weights each phone bundles.");

  console.log("The patient's home on three platforms · the on-record sentence from passport.json under the readings on all three; the next visit ordered by nextFirst on all three; Android's nurse the visit's own or nobody; the CI document reads each phone's faces from the platform.");
}

/* ─── The storefront: real product types, generated pictures, and a welcome monitor that is a plan ───
   2 October 2026. The founder asked for a shop with real products, proper pictures, what each device
   reads and what the doctor sees, and a free device on sign-up. Each of those is a place a shop can
   overstate itself, so each is held here as arithmetic or absence rather than as a sentence:

   1. A kit has no price. It is the sum of its items wherever it is drawn, and the phones' generated
      copies add it up too — a typed kit price is five numbers waiting to drift.
   2. What a device measures is its instrument's, from capture.json, or record measures it is typed
      into; never a list of its own. Each measure is in records.json or has a sentence saying the
      record does not hold it — so no listing implies a doctor sees a weight the record cannot keep.
   3. Every "who sees what" line exists, holds for the product it is on (an urgent far-outside answer
      only for a measure with far-outside bounds, the live panel only for a measure it streams), and
      says `in-preview` only with a file on disk as evidence.
   4. No maker is named, anywhere a shopper or a prompt could read one: a brand implies a reseller
      agreement that does not exist.
   5. No payment path: nothing the storefront runs opens a request, and the shop entry's policy
      reaches no other origin.
   6. Every product and kit has a picture that exists, is the size the contract says and under its
      cap, on the web and on both phones; alt text; provenance in shop/images.json; and the
      "Illustrative image" label is drawn by every surface that draws a picture. The pictures are
      not under /shop/, because nginx answers every path under /shop/ with shop.html.
   7. The welcome monitor is `planned` while the accounts capability is not connected, its label
      says so, its refusal is drawn wherever it is, and sign-up loads it behind a dynamic import.
   8. Every price sits inside a reference range with the day it was checked and the kind of retailer
      it came from. */
{
  const { shopDerivation } = await import("./emit-shop.mjs");
  const sf = (m) => { throw new Error(`The storefront: ${m}`); };
  const d = shopDerivation();
  const { shop } = d;
  const art = JSON.parse(read("packages/catalog/shop/images.json"));
  const caps = JSON.parse(read("packages/catalog/capabilities.json"));
  const capList = caps.capabilities ?? caps;
  const webShop = read("apps/web/src/features/Shop.tsx");
  const webLib = read("apps/web/src/lib/shop-catalogue.ts");
  const webWelcome = read("apps/web/src/features/WelcomeDevice.tsx");
  const onboarding = read("apps/web/src/features/Onboarding.tsx");
  const iosShop = read("apps/ios/MyThuso/Features/ShopView.swift");
  const androidShop = read("apps/android/app/src/main/java/za/co/mythuso/ui/ShopScreens.kt");
  const shopFile = (end) => emitShop().find((f) => f.path.endsWith(end)).content;
  const [iosData, androidData] = [shopFile("ShopData.swift"), shopFile("ShopData.kt")];
  const productIds = new Set(shop.products.map((p) => p.id));

  /* 1. */
  for (const kit of shop.kits) {
    for (const field of ["price", "priceCents", "total", "cost"]) if (field in kit) sf(`the kit "${kit.id}" carries a "${field}". A kit costs the sum of its items, worked out wherever it is shown.`);
    if (kit.items.length < 2) sf(`the kit "${kit.id}" has fewer than two items, which is a product rather than a kit.`);
    for (const id of kit.items) if (!productIds.has(id)) sf(`the kit "${kit.id}" names "${id}", which the shop does not sell.`);
  }
  if (!/export const kitCents = /.test(webLib) || /kit\.price\b/.test(webShop)) sf("the web no longer adds a kit up from its items in lib/shop-catalogue.ts.");
  if (!/static func priceCents\(of kit: Kit\)/.test(iosData) || /priceCents: \d+, stock: \d+[^\n]*\n[^\n]*items:/.test(iosData)) sf("ShopData.swift no longer adds a kit up from its items.");
  if (!/fun priceCents\(kit: ShopKit\)/.test(androidData)) sf("ShopData.kt no longer adds a kit up from its items.");

  /* 2. */
  const recordIds = new Set(d.records.observations.measures.map((m) => m.id));
  const captureIds = new Set(d.capture.devices.map((x) => x.id));
  for (const p of shop.products) {
    if ("measures" in p) sf(`"${p.id}" lists its own measures. They are its instrument's in capture.json, or the record measures it is typed into.`);
    if (p.captureKind && p.typedMeasures) sf(`"${p.id}" is both a Bluetooth instrument and typed in. It is one or the other.`);
    if (p.captureKind && !captureIds.has(p.captureKind)) sf(`"${p.id}" names the instrument "${p.captureKind}", which packages/catalog/capture.json has not got.`);
    for (const m of d.measuresOf(p))
      if (!recordIds.has(m) && !shop.notInRecord[m]?.sentence) sf(`"${p.id}" measures "${m}", which records.json does not hold and notInRecord says nothing about — the listing would imply a doctor sees it.`);
    if (p.needsReading && d.measuresOf(p).length === 0) sf(`"${p.id}" says it produces a reading but measures nothing.`);
    if (p.captureKind === "bp-cuff" && !shop.validations.some((v) => v.id === p.validation)) sf(`"${p.id}" is a blood pressure monitor with no validation. A monitor is sold only from a published validation list.`);
    if (p.captureKind === "pulse-oximeter" && !(p.caveats ?? []).includes("skin-pigmentation")) sf(`"${p.id}" is a pulse oximeter without the caveat about darker skin.`);
    if (!shop.regulatory.classes.some((c) => c.id === p.sahpra)) sf(`"${p.id}" has no regulatory class from shop.json's list.`);
  }
  for (const c of shop.caveats) if (!c.sources?.length || c.sources.some((s) => !/^https:\/\//.test(s.url))) sf(`the caveat "${c.id}" cites no source.`);
  for (const v of shop.validations) if (!/^https:\/\//.test(v.url)) sf(`the validation "${v.id}" names no list to check a model against.`);

  /* 3. */
  for (const [id, line] of Object.entries(shop.seenLines)) {
    if (id.startsWith("_")) continue;
    if (!["in-preview", "planned"].includes(line.status)) sf(`the line "${id}" is "${line.status}". A line is in this preview, with evidence, or planned.`);
    if (line.status === "in-preview" && !(line.evidence && existsSync(line.evidence))) sf(`the line "${id}" says it is in this preview and names no file that makes it so.`);
    if (/\d/.test(line.text.replace("{trendNeeds}", ""))) sf(`the line "${id}" types a number. A number in a promise comes from the contract that owns it.`);
  }
  for (const p of shop.products)
    for (const [audience, ids] of Object.entries(p.sees ?? {}))
      for (const id of ids) {
        const line = shop.seenLines[id];
        if (!line) sf(`"${p.id}" promises the line "${id}", which seenLines has not got.`);
        if (line.audience !== audience) sf(`"${p.id}" lists "${id}" under ${audience}, and the line is the ${line.audience}'s.`);
        if (!d.holds(p, line.needs)) sf(`"${p.id}" promises "${id}", which needs "${line.needs}" — and nothing "${p.id}" measures meets it.`);
      }

  /* 4. */
  const brand = new RegExp(`\\b(${shop.brandsNeverNamed.map((b) => b.replace(/[-]/g, "\\-")).join("|")})\\b`, "i");
  const shelf = JSON.stringify({ products: shop.products, kits: shop.kits, welcome: shop.welcome, validations: shop.validations, caveats: shop.caveats, seenLines: shop.seenLines, prompts: art.images });
  const named = shelf.match(brand);
  if (named) sf(`a listing, a picture's description or a prompt names "${named[0]}". Nothing in the shop names a maker.`);
  for (const [file, code] of [["Shop.tsx", webShop], ["ShopView.swift", iosShop], ["ShopScreens.kt", androidShop], ["WelcomeDevice.tsx", webWelcome]]) {
    const hit = code.match(brand);
    if (hit) sf(`${file} names "${hit[0]}".`);
  }

  /* 5. */
  for (const [file, code] of [["apps/web/src/features/Shop.tsx", webShop], ["apps/web/src/lib/shop-catalogue.ts", webLib], ["apps/web/src/lib/commerce.ts", read("apps/web/src/lib/commerce.ts")], ["apps/web/src/features/WelcomeDevice.tsx", webWelcome]]) {
    if (/\bfetch\(|XMLHttpRequest|sendBeacon|new WebSocket|window\.open\(|['"`]\/api\//.test(code)) sf(`${file} opens a request. Nothing in the storefront reaches anything: no card is charged and no order is placed.`);
    if (/\b(payfast|yoco|peach|stripe|paystack|ozow|checkout)\b/i.test(code.replace(/\/\*[\s\S]*?\*\//g, ""))) sf(`${file} names a payment provider or a checkout.`);
  }
  /* The storefront is its own entry so the patient's first view never pays for it — and an entry that
     imports a module the first view also imports makes Rollup split that module into a chunk of its own,
     which the first view then downloads in more pieces. Measured at +0.8 kB on 2 October 2026, from
     capture.json, records.json and NotConnected; the storefront reads the generated projection instead. */
  const firstViewShared = /catalog\/(capture|records|reading-questions|case|live-vitals|devices)\.json|components\/NotConnected/;
  for (const [file, code] of [["apps/web/src/features/Shop.tsx", webShop], ["apps/web/src/lib/shop-catalogue.ts", webLib]])
    if (firstViewShared.test(code)) sf(`${file} imports a contract or component the patient app's first view also imports. Read lib/shop-derived.generated.ts, which scripts/emit-shop.mjs writes.`);
  const shopPolicy = read("apps/web/shop.html").match(/http-equiv="Content-Security-Policy" content="[^"]*connect-src ([^;"]+)/)?.[1] ?? "";
  if (shopPolicy.split(/\s+/).some((s) => s && !["'self'", "ws:"].includes(s))) sf(`apps/web/shop.html lets the page connect to ${shopPolicy}. The storefront reaches no payment provider, because there is no payment.`);
  if (webShop.indexOf("refusal('no-payment')") < 0 || webShop.indexOf("refusal('no-payment')") > webShop.indexOf("<Shelf ")) sf("Shop.tsx no longer draws the no-payment refusal above the shelf.");

  /* 6. */
  const webpSize = (buf) => {
    const kind = buf.toString("ascii", 12, 16);
    if (kind === "VP8 ") return [buf.readUInt16LE(26) & 0x3fff, buf.readUInt16LE(28) & 0x3fff];
    if (kind === "VP8L") { const b = buf.readUInt32LE(21); return [(b & 0x3fff) + 1, ((b >> 14) & 0x3fff) + 1]; }
    if (kind === "VP8X") return [buf.readUIntLE(24, 3) + 1, buf.readUIntLE(27, 3) + 1];
    return [0, 0];
  };
  const jpegSize = (buf) => {
    for (let i = 2; i < buf.length;) {
      const marker = buf[i + 1], length = buf.readUInt16BE(i + 2);
      if (marker >= 0xc0 && marker <= 0xc3) return [buf.readUInt16BE(i + 7), buf.readUInt16BE(i + 5)];
      i += 2 + length;
    }
    return [0, 0];
  };
  const img = shop.images;
  if (img.dir.startsWith("/shop/")) sf(`the pictures are served from ${img.dir}, and deploy/nginx/mythuso.conf answers every path under /shop/ with shop.html.`);
  if (!art.generator || !art.model || !/^\d{4}-\d{2}-\d{2}$/.test(art.made ?? "")) sf("packages/catalog/shop/images.json does not say which generator and model made the pictures, or on which day.");
  const pictured = [...shop.products, ...shop.kits];
  for (const item of pictured) {
    if (!item.image?.alt || !/\.$/.test(item.image.alt) || item.image.alt.length < 20) sf(`"${item.id}" has no alt text that describes its picture in a sentence.`);
    if (!art.images[item.id]?.prompt || !art.images[item.id]?.asset) sf(`"${item.id}" has a picture with no provenance in shop/images.json.`);
    const checks = [
      [`apps/web/public${img.dir}${item.id}.webp`, img.width, img.height, img.maxBytes, webpSize],
      [`apps/web/public${img.dir}${item.id}${img.small.suffix}.webp`, img.small.width, img.small.height, img.maxBytes, webpSize],
      [`apps/ios/MyThuso/Assets.xcassets/Shop-${item.id}.imageset/shop-${item.id}.jpg`, img.native.width, img.native.height, img.native.maxBytes, jpegSize],
      [`apps/android/app/src/main/res/drawable-nodpi/shop_${item.id.replace(/-/g, "_")}.webp`, img.native.width, img.native.height, img.native.maxBytes, webpSize],
    ];
    for (const [file, w, h, cap, size] of checks) {
      if (!existsSync(file)) sf(`"${item.id}" has no picture at ${file}.`);
      const buf = readFileSync(file);
      if (buf.length > cap) sf(`${file} is ${buf.length} bytes, over the ${cap} the contract allows. The shop is opened on metered data.`);
      const [aw, ah] = size(buf);
      if (aw !== w || ah !== h) sf(`${file} is ${aw}×${ah}, and the contract says ${w}×${h}.`);
    }
  }
  for (const id of Object.keys(art.images)) if (!pictured.some((p) => p.id === id)) sf(`shop/images.json describes "${id}", which the shop does not list.`);
  if (!/shop\.images\.label/.test(webShop) || !/images\.label/.test(webWelcome) || !/ShopData\.imageLabel/.test(iosShop) || !/ShopData\.imageLabel/.test(androidShop))
    sf(`a surface draws a picture without the "${img.label}" label: Shop.tsx, WelcomeDevice.tsx, ShopView.swift and ShopScreens.kt each read it from the contract.`);

  /* 7. */
  const w = shop.welcome;
  const accounts = capList.find((c) => c.id === "accounts");
  if (!accounts?.connected && w.status !== "planned") sf(`the welcome monitor is "${w.status}" while sign-up is not connected. It is a planned launch offer until accounts are live.`);
  if (!/planned/i.test(w.label) || !/not live/i.test(w.label)) sf("the welcome monitor's label no longer says it is planned and that sign-up is not live.");
  if (!productIds.has(w.productId) || !shop.products.find((p) => p.id === w.productId).welcome) sf("the welcome monitor names a product the shop does not mark as the welcome device.");
  if (!shop.refusals.some((r) => r.id === "welcome-not-live")) sf("the welcome-not-live refusal is gone.");
  if (!/welcome\.label/.test(webShop) || !/refusal\('welcome-not-live'\)/.test(webShop)) sf("Shop.tsx draws the welcome monitor without its label or its refusal.");
  if (!/welcome\.label/.test(webWelcome) || !/'welcome-not-live'/.test(webWelcome)) sf("WelcomeDevice.tsx draws the welcome monitor without its label or its refusal.");
  if (!/ShopData\.Welcome\.label/.test(iosShop) || !/"welcome-not-live"/.test(iosShop) || !/ShopWelcome\.label/.test(androidShop) || !/"welcome-not-live"/.test(androidShop))
    sf("a phone draws the welcome monitor without its label or its refusal.");
  if (!/lazy\(\(\) => import\('\.\/WelcomeDevice'\)\)/.test(onboarding) || /^import[^\n]*WelcomeDevice/m.test(onboarding)) sf("sign-up loads the welcome monitor statically. It sits behind a dynamic import so the patient entry does not grow.");
  if (!/^https:\/\//.test(w.why.url) || !(w.why.women > 0 && w.why.men > 0)) sf("the welcome monitor's reason no longer cites the survey it comes from.");
  if (!(w.cost.wholesaleShare.low < w.cost.wholesaleShare.high && w.cost.wholesaleShare.high < 1) || "amount" in w.cost) sf("the welcome monitor's cost is typed rather than worked out from the reference price and a stated share.");

  /* 8. */
  const today = new Date().toISOString().slice(0, 10);
  for (const p of shop.products) {
    const r = p.reference;
    if (!r || !(r.low <= p.price && p.price <= r.high)) sf(`"${p.id}" costs R${p.price}, outside its reference range.`);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(r.checked) || r.checked > today) sf(`"${p.id}" has a reference price with no day it was checked.`);
    if (!r.from || r.from.length < 10) sf(`"${p.id}" has a reference price that does not say what kind of retailer it came from.`);
    if (r.low % 10 || r.high % 10) sf(`"${p.id}" has a reference range to the rand. A reference price is rounded; a figure to the rand claims a precision nobody has.`);
  }

  const kitTotals = shop.kits.map((k) => `${k.name} R${d.kitCents(k) / 100}`).join(", ");
  console.log(`The storefront · ${shop.products.length} products and ${shop.kits.length} kits priced from their items (${kitTotals}); every measure from capture.json and records.json; ${Object.keys(shop.seenLines).length - 1} who-sees-what lines held to what each product measures, ${Object.values(shop.seenLines).filter((l) => l.status === "in-preview").length} of them in this preview with evidence; ${pictured.length} pictures × 4 files sized and capped, each with alt text and provenance; no maker named; no request opened; the welcome monitor planned while sign-up is not live; every price inside a dated reference range.`);
}

/* The triage markers are the officer's lines, and only theirs — 2 October 2026 */
/* The founder asked for the doctor's Triage screen to mark each reading good or bad against standard demo
   readings an officer changes later. packages/catalog/triage-markers.json is that officer's file. Held here:
   1. Every observation records.json declares has a line, and no line names an observation it does not.
   2. Each alert line sits on or outside the edge of the indicative range, so no reading is both green and
      red, and a low line is below a high one.
   3. The file claims a review only with a reviewer and a day, and while it claims none the screen says the
      lines are demo defaults — governanceLine() is what draws the banner, and it is drawn.
   4. Nothing else types a line: lib/triage-markers.ts and the Triage screen read the contract, and a marker
      is never added into a figure about a person.
   5. The preview's readings are for sandbox patients who consented, and for observations that exist. */
{
  const tmFile = "packages/catalog/triage-markers.json";
  const tm = JSON.parse(read(tmFile));
  const tmFail = (message) => { throw new Error(`The triage markers: ${message}`); };
  const obs = new Map(measures.map((m) => [m.id, m]));
  /* 1. */
  for (const m of measures) if (!tm.lines.some((l) => l.id === m.id)) tmFail(`${tmFile} has no alert line for "${m.id}", which records.json observes. A reading with no line could never be marked for action.`);
  for (const l of tm.lines) if (!obs.has(l.id)) tmFail(`${tmFile} draws an alert line for "${l.id}", which records.json does not observe.`);
  /* 2. */
  for (const l of tm.lines) {
    const m = obs.get(l.id);
    for (const side of ["actAtOrBelow", "actAtOrAbove"])
      if (l[side] !== null && typeof l[side] !== "number") tmFail(`"${l.id}" ${side} is ${JSON.stringify(l[side])}; a line is a number, or null where the measure has none on that side.`);
    if (l.actAtOrBelow === null && l.actAtOrAbove === null) tmFail(`"${l.id}" has no alert line on either side, so nothing it reads could ever be marked for action.`);
    if (l.actAtOrBelow !== null && l.actAtOrBelow > m.low) tmFail(`"${l.id}" acts at or below ${l.actAtOrBelow}, inside its indicative range ${m.low}–${m.high}: a reading would be in range and past the alert line at once.`);
    if (l.actAtOrAbove !== null && l.actAtOrAbove <= m.high) tmFail(`"${l.id}" acts at or above ${l.actAtOrAbove}, on or inside its indicative range ${m.low}–${m.high}: a reading would be in range and past the alert line at once.`);
  }
  /* 3. */
  const g = tm.governance;
  if (!["demo-defaults", "reviewed"].includes(g.status)) tmFail(`governance.status is "${g.status}"; it is demo-defaults or reviewed.`);
  if (g.status === "reviewed" && (!g.reviewedBy || !/^\d{4}-\d{2}-\d{2}$/.test(g.reviewedOn ?? ""))) tmFail("the lines claim a review with no reviewer or no day. A threshold that decides what is drawn red belongs to a named role under a date.");
  if (g.status !== "reviewed" && (g.reviewedBy || g.reviewedOn)) tmFail("the lines name a reviewer while still calling themselves demo defaults. Either the review happened and the status says so, or it did not.");
  if (!g.owner || !g.banner || !g.source) tmFail("governance lost its owner, its banner or its source.");
  /* 4. */
  const tmLib = "apps/web/src/lib/triage-markers.ts", tmScreen = "apps/web/src/features/DoctorPages.tsx";
  const lib = read(tmLib), screen = read(tmScreen);
  if (!/import contract from '[./]*packages\/catalog\/triage-markers\.json'/.test(lib) || !/from '\.\/observations'/.test(lib)) tmFail(`${tmLib} no longer reads its lines from the contract and its green band from lib/observations.`);
  for (const l of tm.lines) for (const f of [tmLib, tmScreen]) {
    const typed = read(f).split("\n").some((line) => line.includes(`'${l.id}'`) && [l.actAtOrBelow, l.actAtOrAbove].some((n) => n !== null && (line.match(/\d+(\.\d+)?/g) || []).map(Number).includes(n)));
    if (typed) tmFail(`${f} types the alert line for "${l.id}". It lives in ${tmFile}, which is the Clinical Governance Lead's to change.`);
  }
  const triage = screen.slice(screen.indexOf("export function DoctorTriage"), screen.indexOf("/* ---- Prescriptions"));
  if (!triage.includes("governanceLine()")) tmFail("the Triage screen draws markers without the governance line, so demo defaults would read as reviewed thresholds.");
  if (/\.reduce\(|\bscore\b/i.test(uncommented(triage))) tmFail("the Triage screen adds markers up. A marker is per reading; a sum of them is an early-warning score nobody has validated.");
  /* 5. */
  const sandbox = read("packages/thusoiq/fixtures.ts");
  for (const r of tm.preview.readings) {
    const p = sandbox.match(new RegExp(`id:'${r.patientId}'[^}]*consent:(true|false)`));
    if (!p) tmFail(`the preview has readings for "${r.patientId}", who is not a sandbox patient in packages/thusoiq/fixtures.ts.`);
    if (p[1] !== "true") tmFail(`the preview has readings for "${r.patientId}", who has not consented to sharing them.`);
    for (const [id, series] of Object.entries(r.series)) {
      if (!obs.has(id)) tmFail(`the preview reads "${id}" for ${r.patientId}, which records.json does not observe.`);
      if (!Array.isArray(series) || !series.length || series.some((v) => typeof v !== "number")) tmFail(`the preview's "${id}" for ${r.patientId} is not a series of numbers, oldest first.`);
    }
  }
  /* 6. The heart and the lungs move at the recorded rate, under the page's pause control, and never under reduced motion. */
  const viCss = read("apps/web/src/features/vital-icons.css").replace(/\/\*[\s\S]*?\*\//g, "");
  for (const m of viCss.matchAll(/([^{}]*)\{[^{}]*animation:(?!\s*none\b)[^;}]*/g))
    if (!m[1].includes("[data-motion='running']")) tmFail(`apps/web/src/features/vital-icons.css animates "${m[1].trim()}" outside [data-motion='running'], where the pause control cannot reach it.`);
  if (!/prefers-reduced-motion:\s*reduce/.test(viCss)) tmFail("apps/web/src/features/vital-icons.css says nothing about a reader who asked for less motion.");
  for (const m of viCss.matchAll(/@keyframes\s+([\w-]+)\s*\{((?:[^{}]|\{[^{}]*\})*)\}/g))
    for (const prop of [...m[2].matchAll(/([a-z-]+)\s*:/g)].map((p) => p[1])) if (prop !== "transform") tmFail(`vital-icons.css's @keyframes ${m[1]} animates ${prop}. Transform only.`);
  if (!/data-motion=\{decor\.reduced \? 'still' : decor\.playing \? 'running' : 'paused'\}/.test(triage)) tmFail("the Triage screen no longer hands its vitals the page's motion flag, so the heart would beat with no way to stop it.");
  console.log(`The triage markers · ${tm.lines.length} alert lines, each on or outside its indicative range, owned by the ${g.owner} and ${g.status === "reviewed" ? `reviewed on ${g.reviewedOn}` : "drawn under the demo banner"}; nothing typed, nothing summed; ${tm.preview.readings.length} consented sandbox patients with readings.`);
}
